-- CounterNest POS Phase 31.7: ingredient lots, expiry, FEFO, recalls, disposal, and production traceability.

create table if not exists public.ingredient_lots (
  id uuid primary key default gen_random_uuid(),
  lot_record_number bigint generated by default as identity,
  shop_id uuid not null references public.shops(id) on delete cascade,
  ingredient_id uuid not null references public.ingredients(id) on delete restrict,
  supplier_id uuid references public.suppliers(id) on delete set null,
  receipt_item_id uuid references public.ingredient_purchase_receipt_items(id) on delete set null,
  lot_code text not null,
  manufactured_on date,
  expires_on date,
  received_quantity numeric(14,3) not null check(received_quantity>0),
  remaining_quantity numeric(14,3) not null check(remaining_quantity>=0 and remaining_quantity<=received_quantity),
  unit_cost_snapshot numeric(14,6) not null check(unit_cost_snapshot>=0),
  status text not null default 'active' check(status in('active','recalled','depleted')),
  recall_reason text,
  received_at timestamptz not null default now(),
  created_by uuid references auth.users(id) on delete restrict,
  updated_at timestamptz not null default now(),
  constraint ingredient_lot_dates check(manufactured_on is null or expires_on is null or manufactured_on<=expires_on)
);

create table if not exists public.ingredient_lot_allocations (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id) on delete cascade,
  lot_id uuid not null references public.ingredient_lots(id) on delete restrict,
  inventory_movement_id uuid not null references public.ingredient_inventory_movements(id) on delete restrict,
  production_batch_id uuid references public.production_batches(id) on delete set null,
  quantity_allocated numeric(14,3) not null check(quantity_allocated>0),
  allocated_at timestamptz not null default now(),
  unique(lot_id,inventory_movement_id)
);

create table if not exists public.ingredient_lot_events (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id) on delete cascade,
  lot_id uuid not null references public.ingredient_lots(id) on delete restrict,
  action text not null check(action in('created','details_updated','allocated','recalled','disposed')),
  quantity numeric(14,3),
  details jsonb not null default '{}'::jsonb,
  performed_by uuid references auth.users(id) on delete restrict,
  created_at timestamptz not null default now()
);

create index if not exists ingredient_lots_shop_expiry_idx on public.ingredient_lots(shop_id,expires_on,status);
create index if not exists ingredient_lots_ingredient_fefo_idx on public.ingredient_lots(ingredient_id,status,expires_on,received_at);
create index if not exists ingredient_lot_allocations_lot_idx on public.ingredient_lot_allocations(lot_id,allocated_at desc);
create index if not exists ingredient_lot_events_lot_idx on public.ingredient_lot_events(lot_id,created_at desc);

alter table public.ingredient_lots enable row level security;
alter table public.ingredient_lot_allocations enable row level security;
alter table public.ingredient_lot_events enable row level security;
drop policy if exists ingredient_lots_admin_select on public.ingredient_lots;
create policy ingredient_lots_admin_select on public.ingredient_lots for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());
drop policy if exists ingredient_lot_allocations_admin_select on public.ingredient_lot_allocations;
create policy ingredient_lot_allocations_admin_select on public.ingredient_lot_allocations for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());
drop policy if exists ingredient_lot_events_admin_select on public.ingredient_lot_events;
create policy ingredient_lot_events_admin_select on public.ingredient_lot_events for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());

-- Preserve existing balances as explicitly untracked opening lots during upgrade.
insert into public.ingredient_lots(shop_id,ingredient_id,lot_code,received_quantity,remaining_quantity,unit_cost_snapshot,status,received_at)
select i.shop_id,i.id,'OPENING-31.7-'||upper(left(i.id::text,8)),i.current_quantity,i.current_quantity,i.average_unit_cost,'active',now()
from public.ingredients i where i.current_quantity>0 and not exists(select 1 from public.ingredient_lots l where l.ingredient_id=i.id);

insert into public.ingredient_lot_events(shop_id,lot_id,action,quantity,details)
select l.shop_id,l.id,'created',l.received_quantity,jsonb_build_object('source','Phase 31.7 opening-balance migration','traceability','untracked')
from public.ingredient_lots l where l.lot_code like 'OPENING-31.7-%' and not exists(select 1 from public.ingredient_lot_events e where e.lot_id=l.id and e.action='created');

create or replace function public.maintain_ingredient_lots_from_movement() returns trigger
language plpgsql security definer set search_path=public as $$
declare v_needed numeric;v_take numeric;v_lot public.ingredient_lots%rowtype;v_production uuid;
begin
  if new.quantity_delta>0 and(new.movement_type in('opening','adjustment','correction') or(new.movement_type='receipt' and new.reference_type='ingredient_receipt')) then
    insert into public.ingredient_lots(shop_id,ingredient_id,lot_code,received_quantity,remaining_quantity,unit_cost_snapshot,status,received_at,created_by)
    values(new.shop_id,new.ingredient_id,'AUTO-'||upper(left(new.id::text,12)),new.quantity_delta,new.quantity_delta,coalesce(new.unit_cost,0),'active',new.created_at,new.created_by) returning * into v_lot;
    insert into public.ingredient_lot_events(shop_id,lot_id,action,quantity,details,performed_by)
    values(new.shop_id,v_lot.id,'created',new.quantity_delta,jsonb_build_object('source','inventory movement','movement_type',new.movement_type,'traceability','untracked'),new.created_by);
    return new;
  end if;
  if new.quantity_delta>=0 or new.movement_type not in('production','waste','adjustment','correction') or new.reference_type='ingredient_lot_disposal' then return new; end if;
  v_needed:=-new.quantity_delta;
  if new.reference_type='production_batch' then v_production:=new.reference_id; end if;
  for v_lot in
    select * from public.ingredient_lots l where l.shop_id=new.shop_id and l.ingredient_id=new.ingredient_id and l.remaining_quantity>0
      and(case when new.movement_type='production' then l.status='active' and(l.expires_on is null or l.expires_on>=current_date) else l.status in('active','recalled') end)
    order by(l.expires_on is null),l.expires_on,l.received_at,l.id for update
  loop
    exit when v_needed<=0;
    v_take:=least(v_needed,v_lot.remaining_quantity);
    update public.ingredient_lots set remaining_quantity=remaining_quantity-v_take,status=case when remaining_quantity-v_take<=0 then 'depleted' else status end,updated_at=now() where id=v_lot.id;
    insert into public.ingredient_lot_allocations(shop_id,lot_id,inventory_movement_id,production_batch_id,quantity_allocated)
    values(new.shop_id,v_lot.id,new.id,v_production,v_take);
    insert into public.ingredient_lot_events(shop_id,lot_id,action,quantity,details,performed_by)
    values(new.shop_id,v_lot.id,'allocated',v_take,jsonb_build_object('movement_type',new.movement_type,'reference_type',new.reference_type,'reference_id',new.reference_id),new.created_by);
    v_needed:=v_needed-v_take;
  end loop;
  if v_needed>0 then
    if new.movement_type='production' then raise exception 'Insufficient usable non-expired, non-recalled ingredient lots for production';
    else raise exception 'Ingredient lot balances do not cover this stock reduction'; end if;
  end if;
  return new;
end $$;

drop trigger if exists maintain_ingredient_lots_trigger on public.ingredient_inventory_movements;
create trigger maintain_ingredient_lots_trigger after insert on public.ingredient_inventory_movements for each row execute function public.maintain_ingredient_lots_from_movement();

-- Phase 31.4 receiving now requires traceability values for each delivered lot.
create or replace function public.receive_ingredient_purchase_order(p_order_id uuid,p_invoice_reference text,p_note text,p_items jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_shop uuid:=public.current_shop_id();v_order public.ingredient_purchase_orders%rowtype;v_line record;v_order_item public.ingredient_purchase_order_items%rowtype;
  v_ingredient public.ingredients%rowtype;v_receipt uuid;v_receipt_item uuid;v_lot uuid;v_balance numeric;v_average numeric;v_count integer:=0;v_new_status text;v_result jsonb:='[]'::jsonb;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  select * into v_order from public.ingredient_purchase_orders where id=p_order_id and shop_id=v_shop for update;
  if v_order.id is null or v_order.status not in('ordered','partially_received') then raise exception 'Open ingredient purchase order not found'; end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array' or jsonb_array_length(coalesce(p_items,'[]'::jsonb))=0 then raise exception 'At least one receipt line is required'; end if;
  insert into public.ingredient_purchase_receipts(shop_id,order_id,supplier_id,invoice_reference,note,received_by)
  values(v_shop,v_order.id,v_order.supplier_id,nullif(trim(p_invoice_reference),''),nullif(trim(p_note),''),auth.uid()) returning id into v_receipt;
  for v_line in select * from jsonb_to_recordset(p_items) as x(order_item_id uuid,quantity_received numeric,actual_unit_cost numeric,lot_code text,manufactured_on date,expires_on date) loop
    select * into v_order_item from public.ingredient_purchase_order_items where id=v_line.order_item_id and order_id=v_order.id and shop_id=v_shop for update;
    if v_order_item.id is null then raise exception 'Purchase-order line not found'; end if;
    if v_line.quantity_received is null or v_line.quantity_received<=0 or v_line.quantity_received>v_order_item.ordered_quantity-v_order_item.received_quantity then raise exception 'Received quantity exceeds the remaining ordered quantity for %',v_order_item.ingredient_name; end if;
    if v_line.actual_unit_cost is null or v_line.actual_unit_cost<0 then raise exception 'Actual unit cost cannot be negative'; end if;
    if nullif(trim(v_line.lot_code),'') is null then raise exception 'Supplier lot or batch code is required for %',v_order_item.ingredient_name; end if;
    if v_line.manufactured_on is not null and v_line.manufactured_on>current_date then raise exception 'Manufacture date cannot be in the future'; end if;
    if v_line.expires_on is not null and v_line.expires_on<current_date then raise exception 'Expired stock cannot be received'; end if;
    if v_line.manufactured_on is not null and v_line.expires_on is not null and v_line.manufactured_on>v_line.expires_on then raise exception 'Expiration date must follow manufacture date'; end if;
    select * into v_ingredient from public.ingredients where id=v_order_item.ingredient_id and shop_id=v_shop for update;
    if v_ingredient.id is null then raise exception 'Ingredient not found'; end if;
    v_balance:=v_ingredient.current_quantity+v_line.quantity_received;
    v_average:=case when v_balance=0 then 0 else((v_ingredient.current_quantity*v_ingredient.average_unit_cost)+(v_line.quantity_received*v_line.actual_unit_cost))/v_balance end;
    insert into public.ingredient_purchase_receipt_items(shop_id,receipt_id,order_item_id,ingredient_id,ingredient_name,base_unit,quantity_received,expected_unit_cost,actual_unit_cost)
    values(v_shop,v_receipt,v_order_item.id,v_ingredient.id,v_ingredient.name,v_ingredient.base_unit,round(v_line.quantity_received,3),v_order_item.expected_unit_cost,round(v_line.actual_unit_cost,6)) returning id into v_receipt_item;
    insert into public.ingredient_lots(shop_id,ingredient_id,supplier_id,receipt_item_id,lot_code,manufactured_on,expires_on,received_quantity,remaining_quantity,unit_cost_snapshot,created_by)
    values(v_shop,v_ingredient.id,v_order.supplier_id,v_receipt_item,trim(v_line.lot_code),v_line.manufactured_on,v_line.expires_on,round(v_line.quantity_received,3),round(v_line.quantity_received,3),round(v_line.actual_unit_cost,6),auth.uid()) returning id into v_lot;
    insert into public.ingredient_lot_events(shop_id,lot_id,action,quantity,details,performed_by)
    values(v_shop,v_lot,'created',round(v_line.quantity_received,3),jsonb_build_object('source','ingredient purchase receipt','receipt_id',v_receipt),auth.uid());
    update public.ingredient_purchase_order_items set received_quantity=received_quantity+round(v_line.quantity_received,3) where id=v_order_item.id;
    update public.ingredients set current_quantity=v_balance,average_unit_cost=round(v_average,6),preferred_supplier_id=v_order.supplier_id,updated_at=now() where id=v_ingredient.id;
    insert into public.ingredient_inventory_movements(shop_id,ingredient_id,movement_type,quantity_delta,unit_cost,balance_after,reason,reference_type,reference_id,created_by)
    values(v_shop,v_ingredient.id,'receipt',round(v_line.quantity_received,3),round(v_line.actual_unit_cost,6),v_balance,'Ingredient purchase order IPO-'||v_order.order_number||' lot '||trim(v_line.lot_code),'ingredient_purchase_receipt',v_receipt,auth.uid());
    v_result:=v_result||jsonb_build_array(jsonb_build_object('ingredient_id',v_ingredient.id,'lot_id',v_lot,'lot_code',trim(v_line.lot_code),'new_balance',v_balance,'average_unit_cost',round(v_average,6)));
    v_count:=v_count+1;
  end loop;
  if v_count=0 then raise exception 'At least one positive receipt line is required'; end if;
  if exists(select 1 from public.ingredient_purchase_order_items where order_id=v_order.id and received_quantity<ordered_quantity) then v_new_status:='partially_received'; else v_new_status:='received'; end if;
  update public.ingredient_purchase_orders set status=v_new_status,completed_at=case when v_new_status='received' then now() else null end where id=v_order.id;
  insert into public.ingredient_purchase_order_events(shop_id,order_id,action,details,performed_by)
  values(v_shop,v_order.id,v_new_status,jsonb_build_object('receipt_id',v_receipt,'invoice_reference',nullif(trim(p_invoice_reference),'')),auth.uid());
  return jsonb_build_object('receipt_id',v_receipt,'order_id',v_order.id,'status',v_new_status,'ingredients',v_result);
end $$;

create or replace function public.update_ingredient_lot(p_lot_id uuid,p_lot_code text,p_manufactured_on date,p_expires_on date) returns void
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_old public.ingredient_lots%rowtype;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  if nullif(trim(p_lot_code),'') is null then raise exception 'Lot code is required'; end if;
  if p_manufactured_on is not null and p_manufactured_on>current_date then raise exception 'Manufacture date cannot be in the future'; end if;
  if p_manufactured_on is not null and p_expires_on is not null and p_manufactured_on>p_expires_on then raise exception 'Expiration date must follow manufacture date'; end if;
  select * into v_old from public.ingredient_lots where id=p_lot_id and shop_id=v_shop for update;
  if v_old.id is null then raise exception 'Ingredient lot not found'; end if;
  update public.ingredient_lots set lot_code=trim(p_lot_code),manufactured_on=p_manufactured_on,expires_on=p_expires_on,updated_at=now() where id=v_old.id;
  insert into public.ingredient_lot_events(shop_id,lot_id,action,details,performed_by)
  values(v_shop,v_old.id,'details_updated',jsonb_build_object('old_lot_code',v_old.lot_code,'lot_code',trim(p_lot_code),'manufactured_on',p_manufactured_on,'expires_on',p_expires_on),auth.uid());
end $$;

create or replace function public.recall_ingredient_lot(p_lot_id uuid,p_reason text) returns void
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_lot public.ingredient_lots%rowtype;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  if length(trim(coalesce(p_reason,'')))<5 then raise exception 'A recall reason of at least 5 characters is required'; end if;
  select * into v_lot from public.ingredient_lots where id=p_lot_id and shop_id=v_shop for update;
  if v_lot.id is null or v_lot.status='depleted' then raise exception 'Available ingredient lot not found'; end if;
  update public.ingredient_lots set status='recalled',recall_reason=trim(p_reason),updated_at=now() where id=v_lot.id;
  insert into public.ingredient_lot_events(shop_id,lot_id,action,quantity,details,performed_by)
  values(v_shop,v_lot.id,'recalled',v_lot.remaining_quantity,jsonb_build_object('reason',trim(p_reason)),auth.uid());
end $$;

create or replace function public.dispose_ingredient_lot(p_lot_id uuid,p_quantity numeric,p_note text) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_lot public.ingredient_lots%rowtype;v_ingredient public.ingredients%rowtype;v_balance numeric;v_movement uuid;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_quantity is null or p_quantity<=0 then raise exception 'Disposal quantity must be greater than zero'; end if;
  if length(trim(coalesce(p_note,'')))<3 then raise exception 'A disposal note of at least 3 characters is required'; end if;
  select * into v_lot from public.ingredient_lots where id=p_lot_id and shop_id=v_shop for update;
  if v_lot.id is null or v_lot.remaining_quantity<p_quantity then raise exception 'Disposal exceeds the lot balance'; end if;
  select * into v_ingredient from public.ingredients where id=v_lot.ingredient_id and shop_id=v_shop for update;
  if v_ingredient.current_quantity<p_quantity then raise exception 'Disposal exceeds the ingredient balance'; end if;
  v_balance:=v_ingredient.current_quantity-p_quantity;
  update public.ingredient_lots set remaining_quantity=remaining_quantity-p_quantity,status=case when remaining_quantity-p_quantity<=0 then 'depleted' else status end,updated_at=now() where id=v_lot.id;
  update public.ingredients set current_quantity=v_balance,updated_at=now() where id=v_ingredient.id;
  insert into public.ingredient_inventory_movements(shop_id,ingredient_id,movement_type,quantity_delta,unit_cost,balance_after,reason,reference_type,reference_id,created_by)
  values(v_shop,v_ingredient.id,'waste',-p_quantity,v_lot.unit_cost_snapshot,v_balance,'Lot disposal: '||trim(p_note),'ingredient_lot_disposal',v_lot.id,auth.uid()) returning id into v_movement;
  insert into public.ingredient_lot_allocations(shop_id,lot_id,inventory_movement_id,quantity_allocated) values(v_shop,v_lot.id,v_movement,p_quantity);
  insert into public.ingredient_lot_events(shop_id,lot_id,action,quantity,details,performed_by) values(v_shop,v_lot.id,'disposed',p_quantity,jsonb_build_object('note',trim(p_note),'movement_id',v_movement),auth.uid());
  return jsonb_build_object('lot_id',v_lot.id,'ingredient_id',v_ingredient.id,'new_lot_balance',v_lot.remaining_quantity-p_quantity,'new_ingredient_balance',v_balance,'estimated_cost',round(p_quantity*v_lot.unit_cost_snapshot,2));
end $$;

create or replace function public.get_ingredient_traceability(p_expiring_days integer default 30) returns jsonb
language plpgsql security definer stable set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_days integer:=greatest(1,least(coalesce(p_expiring_days,30),365));
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  return jsonb_build_object(
    'summary',(select jsonb_build_object(
      'active_lots',count(*) filter(where status='active' and remaining_quantity>0),
      'expiring_lots',count(*) filter(where status='active' and remaining_quantity>0 and expires_on between current_date and current_date+v_days),
      'expired_lots',count(*) filter(where status='active' and remaining_quantity>0 and expires_on<current_date),
      'recalled_lots',count(*) filter(where status='recalled' and remaining_quantity>0),
      'untracked_lots',count(*) filter(where status='active' and remaining_quantity>0 and(lot_code like 'OPENING-31.7-%' or lot_code like 'AUTO-%')),
      'lot_value',coalesce(sum(remaining_quantity*unit_cost_snapshot) filter(where remaining_quantity>0),0)
    ) from public.ingredient_lots where shop_id=v_shop),
    'lots',(select coalesce(jsonb_agg(to_jsonb(x) order by x.sort_rank,x.expires_on nulls last,x.ingredient_name,x.lot_code),'[]'::jsonb) from(
      select l.id,l.lot_record_number,l.ingredient_id,i.name ingredient_name,i.base_unit,l.supplier_id,s.name supplier_name,l.lot_code,l.manufactured_on,l.expires_on,l.received_quantity,l.remaining_quantity,l.unit_cost_snapshot,l.status,l.recall_reason,l.received_at,
        case when l.status='recalled' then 'recalled' when l.status='depleted' or l.remaining_quantity=0 then 'depleted' when l.expires_on<current_date then 'expired' when l.expires_on<=current_date+v_days then 'expiring' when l.lot_code like 'OPENING-31.7-%' or l.lot_code like 'AUTO-%' then 'untracked' else 'active' end calculated_status,
        case when l.status='recalled' then 0 when l.expires_on<current_date and l.remaining_quantity>0 then 1 when l.expires_on<=current_date+v_days and l.remaining_quantity>0 then 2 when l.lot_code like 'OPENING-31.7-%' or l.lot_code like 'AUTO-%' then 3 when l.status='active' then 4 else 5 end sort_rank,
        (select coalesce(jsonb_agg(jsonb_build_object('allocated_at',a.allocated_at,'quantity',a.quantity_allocated,'movement_type',m.movement_type,'reference_type',m.reference_type,'production_batch_id',a.production_batch_id,'batch_number',pb.batch_number,'product_name',pb.product_name) order by a.allocated_at desc),'[]'::jsonb) from public.ingredient_lot_allocations a join public.ingredient_inventory_movements m on m.id=a.inventory_movement_id left join public.production_batches pb on pb.id=a.production_batch_id where a.lot_id=l.id) usage
      from public.ingredient_lots l join public.ingredients i on i.id=l.ingredient_id left join public.suppliers s on s.id=l.supplier_id where l.shop_id=v_shop
    )x),
    'recent_events',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from(
      select e.id,e.created_at,e.action,e.quantity,e.details,l.lot_code,i.name ingredient_name,coalesce(sp.display_name,'System migration') performed_by_name from public.ingredient_lot_events e join public.ingredient_lots l on l.id=e.lot_id join public.ingredients i on i.id=l.ingredient_id left join public.staff_profiles sp on sp.user_id=e.performed_by and sp.shop_id=e.shop_id where e.shop_id=v_shop order by e.created_at desc limit 100
    )x)
  );
end $$;

create or replace function public.export_supply_operations_backup() returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  return jsonb_build_object(
    'schema_version','1.9.0','exported_at',now(),'shop_id',v_shop,
    'ingredient_purchase_orders',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_orders t where shop_id=v_shop),
    'ingredient_purchase_order_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_order_items t where shop_id=v_shop),
    'ingredient_purchase_order_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_order_events t where shop_id=v_shop),
    'ingredient_purchase_receipts',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_receipts t where shop_id=v_shop),
    'ingredient_purchase_receipt_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_receipt_items t where shop_id=v_shop),
    'inventory_waste_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.inventory_waste_events t where shop_id=v_shop),
    'ingredient_lots',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_lots t where shop_id=v_shop),
    'ingredient_lot_allocations',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_lot_allocations t where shop_id=v_shop),
    'ingredient_lot_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_lot_events t where shop_id=v_shop)
  );
end $$;

-- Phase 31.7 acceptance adds lot-to-ledger consistency and expiry/recall warnings.
create or replace function public.run_phase31_operational_acceptance(p_notes text default null) returns jsonb
language plpgsql security definer set search_path=public as $$
declare
  v_shop uuid:=public.current_shop_id();v_admins integer;v_products integer;v_negative integer;v_empty_recipes integer;v_invalid_recipe_items integer;v_overdue_batches integer;v_uncosted integer;v_recent_backup boolean;v_invalid_orders integer;v_overdue_orders integer;v_lot_gaps integer;v_expired integer;v_recalled integer;v_checks jsonb;v_status text;v_id uuid;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  select count(*) into v_admins from public.staff_profiles where shop_id=v_shop and active and role='admin';select count(*) into v_products from public.products where shop_id=v_shop and active;select count(*) into v_negative from public.ingredients where shop_id=v_shop and current_quantity<0;
  select count(*) into v_empty_recipes from public.product_recipes pr where pr.shop_id=v_shop and pr.active and not exists(select 1 from public.recipe_items ri where ri.recipe_id=pr.id);
  select count(*) into v_invalid_recipe_items from public.recipe_items ri join public.product_recipes pr on pr.id=ri.recipe_id join public.ingredients i on i.id=ri.ingredient_id where pr.shop_id=v_shop and(ri.shop_id<>v_shop or i.shop_id<>v_shop or not i.active);
  select count(*) into v_overdue_batches from public.production_batches where shop_id=v_shop and status='scheduled' and scheduled_date<current_date;select count(*) into v_uncosted from public.products where shop_id=v_shop and active and coalesce(cost_price,0)=0;select exists(select 1 from public.backup_exports where shop_id=v_shop and requested_at>=now()-interval '30 days') into v_recent_backup;
  select count(*) into v_invalid_orders from public.ingredient_purchase_orders po join public.suppliers s on s.id=po.supplier_id where po.shop_id=v_shop and po.status in('ordered','partially_received') and(not s.active or not exists(select 1 from public.ingredient_purchase_order_items i where i.order_id=po.id));select count(*) into v_overdue_orders from public.ingredient_purchase_orders where shop_id=v_shop and status in('ordered','partially_received') and expected_date<current_date;
  select count(*) into v_lot_gaps from public.ingredients i where i.shop_id=v_shop and abs(i.current_quantity-coalesce((select sum(l.remaining_quantity) from public.ingredient_lots l where l.ingredient_id=i.id),0))>0.001;
  select count(*) into v_expired from public.ingredient_lots where shop_id=v_shop and status='active' and remaining_quantity>0 and expires_on<current_date;select count(*) into v_recalled from public.ingredient_lots where shop_id=v_shop and status='recalled' and remaining_quantity>0;
  v_checks:=jsonb_build_array(
    jsonb_build_object('id','active_admin','label','At least one active administrator','status',case when v_admins>0 then 'pass' else 'fail' end,'required',true,'detail',v_admins||' active administrator(s)'),jsonb_build_object('id','active_products','label','Active product catalog','status',case when v_products>0 then 'pass' else 'fail' end,'required',true,'detail',v_products||' active product(s)'),jsonb_build_object('id','ingredient_balances','label','No negative ingredient balances','status',case when v_negative=0 then 'pass' else 'fail' end,'required',true,'detail',v_negative||' invalid balance(s)'),jsonb_build_object('id','recipe_items','label','Active recipes contain ingredients','status',case when v_empty_recipes=0 then 'pass' else 'fail' end,'required',true,'detail',v_empty_recipes||' empty active recipe(s)'),jsonb_build_object('id','recipe_scope','label','Recipe ingredients are active and shop-scoped','status',case when v_invalid_recipe_items=0 then 'pass' else 'fail' end,'required',true,'detail',v_invalid_recipe_items||' invalid recipe line(s)'),jsonb_build_object('id','supply_orders','label','Open ingredient orders have active suppliers and lines','status',case when v_invalid_orders=0 then 'pass' else 'fail' end,'required',true,'detail',v_invalid_orders||' invalid open order(s)'),jsonb_build_object('id','lot_ledger','label','Ingredient lot totals match inventory balances','status',case when v_lot_gaps=0 then 'pass' else 'fail' end,'required',true,'detail',v_lot_gaps||' ingredient lot mismatch(es)'),jsonb_build_object('id','recent_backup','label','Verified backup created in the last 30 days','status',case when v_recent_backup then 'pass' else 'fail' end,'required',true,'detail',case when v_recent_backup then 'Recent backup record found' else 'Create and verify a fresh backup' end),jsonb_build_object('id','expired_lots','label','No expired ingredient stock remains available','status',case when v_expired=0 then 'pass' else 'warning' end,'required',false,'detail',v_expired||' expired lot(s) require disposal'),jsonb_build_object('id','recalled_lots','label','No recalled ingredient stock remains available','status',case when v_recalled=0 then 'pass' else 'warning' end,'required',false,'detail',v_recalled||' recalled lot(s) require disposition'),jsonb_build_object('id','overdue_batches','label','No overdue scheduled production','status',case when v_overdue_batches=0 then 'pass' else 'warning' end,'required',false,'detail',v_overdue_batches||' overdue batch(es)'),jsonb_build_object('id','overdue_supply','label','No overdue ingredient deliveries','status',case when v_overdue_orders=0 then 'pass' else 'warning' end,'required',false,'detail',v_overdue_orders||' overdue ingredient order(s)'),jsonb_build_object('id','product_costs','label','Active products have a unit cost','status',case when v_uncosted=0 then 'pass' else 'warning' end,'required',false,'detail',v_uncosted||' uncosted product(s)')
  );
  v_status:=case when v_admins=0 or v_products=0 or v_negative>0 or v_empty_recipes>0 or v_invalid_recipe_items>0 or v_invalid_orders>0 or v_lot_gaps>0 or not v_recent_backup then 'failed' when v_expired>0 or v_recalled>0 or v_overdue_batches>0 or v_overdue_orders>0 or v_uncosted>0 then 'warning' else 'passed' end;
  insert into public.operational_acceptance_runs(shop_id,release_version,phase,status,checks,notes,run_by) values(v_shop,'1.9.0','31.7',v_status,v_checks,nullif(trim(p_notes),''),auth.uid()) returning id into v_id;
  return jsonb_build_object('id',v_id,'release_version','1.9.0','phase','31.7','status',v_status,'checks',v_checks,'notes',nullif(trim(p_notes),''),'run_at',now());
end $$;

revoke all on function public.receive_ingredient_purchase_order(uuid,text,text,jsonb) from public;
revoke all on function public.update_ingredient_lot(uuid,text,date,date) from public;
revoke all on function public.recall_ingredient_lot(uuid,text) from public;
revoke all on function public.dispose_ingredient_lot(uuid,numeric,text) from public;
revoke all on function public.get_ingredient_traceability(integer) from public;
revoke all on function public.export_supply_operations_backup() from public;
revoke all on function public.run_phase31_operational_acceptance(text) from public;
grant execute on function public.receive_ingredient_purchase_order(uuid,text,text,jsonb) to authenticated;
grant execute on function public.update_ingredient_lot(uuid,text,date,date) to authenticated;
grant execute on function public.recall_ingredient_lot(uuid,text) to authenticated;
grant execute on function public.dispose_ingredient_lot(uuid,numeric,text) to authenticated;
grant execute on function public.get_ingredient_traceability(integer) to authenticated;
grant execute on function public.export_supply_operations_backup() to authenticated;
grant execute on function public.run_phase31_operational_acceptance(text) to authenticated;
